function makeElevatorMoveStep(targetFloor) {
    const targetY = floorY(targetFloor);
    return {
        update: function (delta) {
            const diff = targetY - elevatorCar.position.y;
            if (Math.abs(diff) < 0.01) {
                elevatorCar.position.y = targetY;
                return true;
            }
            const step = ELEVATOR_SPEED * delta;
            elevatorCar.position.y += Math.abs(diff) <= step ? diff : Math.sign(diff) * step;
            return false;
        }
    };
}
