    const shape = new THREE.Shape();
    shape.moveTo(-halfW, -halfD);
    shape.lineTo(halfW, -halfD);
    shape.lineTo(halfW, halfD);
    shape.lineTo(-halfW, halfD);
    shape.closePath();
    if (withHole) {
        const holePath = new THREE.Path();
        const halfSW = SHAFT_WIDTH / 2;
        const halfSD = SHAFT_DEPTH / 2;
        holePath.moveTo(-halfSW, -halfSD);
