1	// elevator.js - Main simulation: building, elevator car, people, animation loop.
2	// Plain classic script (no modules). Depends on THREE (CDN) and createPerson()
3	// from person.js, which must be loaded first.
4	
5	// --- Required constants (top-level, bare names) ---
6	const FLOOR_HEIGHT = 3;
7	const FLOOR_COUNT = 6;
8	const BUILDING_WIDTH = 20;
9	const BUILDING_DEPTH = 15;
10	const SHAFT_WIDTH = 5;
11	const SHAFT_DEPTH = 5;
12	const ELEVATOR_SPEED = 2;
13	const PERSON_MOVE_SPEED = 1;
14	
15	// --- Shared simulation globals ---
16	let scene = null;
17	let camera = null;
18	let renderer = null;
19	let controls = null;
20	let elevatorCar = null;
21	let people = [];
22	
23	let emptyFloor = FLOOR_COUNT - 1;
24	let speedMultiplier = 1;
25	let simulationTime = 0;
26	let lastFrameTime = 0;
27	
28	let animationQueue = [];
29	let currentStep = null;
30	let doorsOpen = false;
31	let doorAnimating = false;
32	
33	// Waiting spot: on the positive Z axis, in front of the elevator doors.
34	const WAIT_Z = SHAFT_DEPTH / 2 + 2;
35	const CAR_INTERIOR_Z = 0;
36	
37	function floorY(floor) {
38	    return floor * FLOOR_HEIGHT;
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Building
43	// ---------------------------------------------------------------------------
44	
45	function createFloorSlabGeometry(withShaftHole) {
46	    const halfWidth = BUILDING_WIDTH / 2;
47	    const halfDepth = BUILDING_DEPTH / 2;
48	    const shape = new THREE.Shape();
49	    shape.moveTo(-halfWidth, -halfDepth);
50	    shape.lineTo(halfWidth, -halfDepth);
51	    shape.lineTo(halfWidth, halfDepth);
52	    shape.lineTo(-halfWidth, halfDepth);
53	    shape.closePath();
54	
55	    if (withShaftHole) {
56	        const halfShaftWidth = SHAFT_WIDTH / 2;
57	        const halfShaftDepth = SHAFT_DEPTH / 2;
58	        const holePath = new THREE.Path();
59	        holePath.moveTo(-halfShaftWidth, -halfShaftDepth);
60	        holePath.lineTo(-halfShaftWidth, halfShaftDepth);
61	        holePath.lineTo(halfShaftWidth, halfShaftDepth);
62	        holePath.lineTo(halfShaftWidth, -halfShaftDepth);
63	        holePath.closePath();
64	        shape.holes.push(holePath);
65	    }
66	
67	    const geometry = new THREE.ExtrudeGeometry(shape, {
68	        depth: 0.2,
69	        bevelEnabled: false
70	    });
71	    // Lay the slab flat: after this the slab occupies y in [0, 0.2].
72	    geometry.rotateX(-Math.PI / 2);
73	    return geometry;
74	}
75	
76	function createBuilding() {
77	    const building = new THREE.Group();
78	    building.name = "building";
79	
80	    const floorMaterial = new THREE.MeshPhongMaterial({
81	        color: 0xcccccc,
82	        transparent: true,
83	        opacity: 0.3,
84	        depthWrite: false,
85	        side: THREE.DoubleSide
86	    });
87	    const wallMaterial = new THREE.MeshPhongMaterial({
88	        color: 0x9999ff,
89	        transparent: true,
90	        opacity: 0.2,
91	        depthWrite: false,
92	        side: THREE.DoubleSide
93	    });
94	    const solidSlabMaterial = new THREE.MeshPhongMaterial({
95	        color: 0xcccccc,
96	        side: THREE.DoubleSide
97	    });
98	
99	    const slabWithHole = createFloorSlabGeometry(true);
100	    const solidSlab = createFloorSlabGeometry(false);
101	
102	    // Solid ground floor (top surface exactly at y = 0).
103	    const ground = new THREE.Mesh(solidSlab, solidSlabMaterial);
104	    ground.position.y = -0.2;
105	    building.add(ground);
106	
107	    // Transparent upper floors with the shaft cutout; top surface at floorY(f).
108	    for (let f = 1; f < FLOOR_COUNT; f++) {
109	        const slab = new THREE.Mesh(slabWithHole, floorMaterial);
110	        slab.position.y = floorY(f) - 0.2;
111	        building.add(slab);
112	    }
113	
114	    // Solid roof on top.
115	    const roof = new THREE.Mesh(solidSlab, solidSlabMaterial);
116	    roof.position.y = floorY(FLOOR_COUNT) - 0.2;
117	    building.add(roof);
118	
119	    // Semi-transparent perimeter walls.
120	    const wallHeight = FLOOR_COUNT * FLOOR_HEIGHT;
121	    const halfWidth = BUILDING_WIDTH / 2;
122	    const halfDepth = BUILDING_DEPTH / 2;
123	
124	    const frontBackGeometry = new THREE.PlaneGeometry(BUILDING_WIDTH, wallHeight);
125	    const frontWall = new THREE.Mesh(frontBackGeometry, wallMaterial);
126	    frontWall.position.set(0, wallHeight / 2, halfDepth);
127	    building.add(frontWall);
128	
129	    const backWall = new THREE.Mesh(frontBackGeometry, wallMaterial);
130	    backWall.position.set(0, wallHeight / 2, -halfDepth);
131	    building.add(backWall);
132	
133	    const sideGeometry = new THREE.PlaneGeometry(BUILDING_DEPTH, wallHeight);
134	    const leftWall = new THREE.Mesh(sideGeometry, wallMaterial);
135	    leftWall.rotation.y = Math.PI / 2;
136	    leftWall.position.set(-halfWidth, wallHeight / 2, 0);
137	    building.add(leftWall);
138	
139	    const rightWall = new THREE.Mesh(sideGeometry, wallMaterial);
140	    rightWall.rotation.y = Math.PI / 2;
141	    rightWall.position.set(halfWidth, wallHeight / 2, 0);
142	    building.add(rightWall);
143	
144	    // Subtle outline of the shaft so the cutout reads clearly.
145	    const shaftOutline = new THREE.LineSegments(
146	        new THREE.EdgesGeometry(new THREE.BoxGeometry(SHAFT_WIDTH, wallHeight, SHAFT_DEPTH)),
147	        new THREE.LineBasicMaterial({ color: 0x667788 })
148	    );
149	    shaftOutline.position.y = wallHeight / 2;
150	    building.add(shaftOutline);
151	
152	    building.traverse(function (child) {
153	        child.renderOrder = 0;
154	    });
155	    return building;
156	}
157	
158	function createGroundPlane() {
159	    const groundPlane = new THREE.Mesh(
160	        new THREE.PlaneGeometry(140, 140),
161	        new THREE.MeshPhongMaterial({ color: 0x2a2f36 })
162	    );
163	    groundPlane.rotation.x = -Math.PI / 2;
164	    groundPlane.position.y = -0.25;
165	    groundPlane.renderOrder = 0;
166	    return groundPlane;
167	}
168	
169	// ---------------------------------------------------------------------------
170	// Elevator car
171	// ---------------------------------------------------------------------------
172	
173	function createElevatorCar() {
174	    const car = new THREE.Group();
175	    car.name = "elevatorCar";
176	
177	    const carWidth = SHAFT_WIDTH - 0.4;
178	    const carDepth = SHAFT_DEPTH - 0.4;
179	    const carHeight = FLOOR_HEIGHT - 0.5;
180	
181	    const frameMaterial = new THREE.MeshPhongMaterial({
182	        color: 0xffff00,
183	        transparent: true,
184	        opacity: 0.5,
185	        depthWrite: false,
186	        side: THREE.DoubleSide
187	    });
188	    const doorMaterial = new THREE.MeshPhongMaterial({
189	        color: 0xcccc00,
190	        transparent: true,
191	        opacity: 0.7,
192	        depthWrite: false,
193	        side: THREE.DoubleSide
194	    });
195	    const solidYellowMaterial = new THREE.MeshPhongMaterial({
196	        color: 0xffff00,
197	        side: THREE.DoubleSide
198	    });
199	
200	    // Solid platform; its top surface sits at the car's local y = 0.
201	    const platform = new THREE.Mesh(
202	        new THREE.BoxGeometry(carWidth, 0.2, carDepth),
203	        solidYellowMaterial
204	    );
205	    platform.position.y = -0.1;
206	    car.add(platform);
207	
208	    // Solid back wall.
209	    const backWall = new THREE.Mesh(
210	        new THREE.PlaneGeometry(carWidth, carHeight),
211	        solidYellowMaterial
212	    );
213	    backWall.position.set(0, carHeight / 2, -carDepth / 2);
214	    car.add(backWall);
215	
216	    // Transparent side walls and ceiling.
217	    const sideGeometry = new THREE.PlaneGeometry(carDepth, carHeight);
218	    const leftWall = new THREE.Mesh(sideGeometry, frameMaterial);
219	    leftWall.rotation.y = Math.PI / 2;
220	    leftWall.position.set(-carWidth / 2, carHeight / 2, 0);
221	    car.add(leftWall);
222	
223	    const rightWall = new THREE.Mesh(sideGeometry, frameMaterial);
224	    rightWall.rotation.y = Math.PI / 2;
225	    rightWall.position.set(carWidth / 2, carHeight / 2, 0);
226	    car.add(rightWall);
227	
228	    const ceiling = new THREE.Mesh(
229	        new THREE.PlaneGeometry(carWidth, carDepth),
230	        frameMaterial
231	    );
232	    ceiling.rotation.x = Math.PI / 2;
233	    ceiling.position.y = carHeight;
234	    car.add(ceiling);
235	
236	    // Visible yellow frame edges.
237	    const frameEdges = new THREE.LineSegments(
238	        new THREE.EdgesGeometry(new THREE.BoxGeometry(carWidth, carHeight, carDepth)),
239	        new THREE.LineBasicMaterial({ color: 0xffff00 })
240	    );
241	    frameEdges.position.y = carHeight / 2;
242	    car.add(frameEdges);
243	
244	    // Two sliding door halves on the front (+Z face). Closed, they meet in the
245	    // middle; open, they retract outward along the X axis.
246	    const doorHeight = carHeight - 0.15;
247	    const doorGeometry = new THREE.BoxGeometry(carWidth / 2, doorHeight, 0.08);
248	
249	    const leftDoor = new THREE.Mesh(doorGeometry, doorMaterial);
250	    leftDoor.position.set(-carWidth / 4, doorHeight / 2 + 0.05, carDepth / 2);
251	    car.add(leftDoor);
252	
253	    const rightDoor = new THREE.Mesh(doorGeometry, doorMaterial);
254	    rightDoor.position.set(carWidth / 4, doorHeight / 2 + 0.05, carDepth / 2);
255	    car.add(rightDoor);
256	
257	    car.leftDoor = leftDoor;
258	    car.rightDoor = rightDoor;
259	
260	    const openTravel = carWidth / 2 - 0.1;
261	    car.userData = {
262	        doorLeftClosedX: -carWidth / 4,
263	        doorRightClosedX: carWidth / 4,
264	        doorLeftOpenX: -carWidth / 4 - openTravel,
265	        doorRightOpenX: carWidth / 4 + openTravel
266	    };
267	
268	    car.traverse(function (child) {
269	        child.renderOrder = 1;
270	    });
271	    return car;
272	}
273	
274	// ---------------------------------------------------------------------------
275	// People
276	// ---------------------------------------------------------------------------
277	
278	function createPeople() {
279	    for (let f = 0; f < FLOOR_COUNT; f++) {
280	        if (f === emptyFloor) {
281	            continue;
282	        }
283	        const person = createPerson();
284	        person.position.set(0, floorY(f), WAIT_Z);
285	        // Face the elevator doors (model faces +Z by default; the doors are at
286	        // smaller Z, so turn around).
287	        person.rotation.y = Math.PI;
288	        person.userData.homeFloor = f;
289	        person.renderOrder = 2;
290	        scene.add(person);
291	        people.push(person);
292	    }
293	}
294	
295	// ---------------------------------------------------------------------------
296	// Sequential animation pipeline (callback/step based)
297	// ---------------------------------------------------------------------------
298	
299	function queueStep(step) {
300	    animationQueue.push(step);
301	}
302	
303	function moveToward(position, axis, target, stepAmount) {
304	    const current = position[axis];
305	    const diff = target - current;
306	    if (Math.abs(diff) < 0.01) {
307	        position[axis] = target;
308	        return true;
309	    }
310	    if (Math.abs(diff) <= stepAmount) {
311	        position[axis] = target;
312	        return true;
313	    }
314	    position[axis] = current + Math.sign(diff) * stepAmount;
315	    return false;
316	}
317	
318	function processSteps(delta) {
319	    if (!currentStep && animationQueue.length > 0) {
320	        currentStep = animationQueue.shift();
321	        if (currentStep.onStart) {
322	            currentStep.onStart();
323	        }
324	    }
325	    if (!currentStep) {
326	        return;
327	    }
328	    const finished = currentStep.update(delta);
329	    if (finished) {
330	        const completedStep = currentStep;
331	        currentStep = null;
332	        if (completedStep.onComplete) {
333	            completedStep.onComplete();
334	        }
335	    }
336	}
337	
338	function makeDelayStep(seconds) {
339	    let elapsed = 0;
340	    return {
341	        update: function (delta) {
342	            elapsed += delta;
343	            return elapsed >= seconds;
344	        }
345	    };
346	}
347	
348	function makeElevatorMoveStep(targetFloor) {
349	    const targetY = floorY(targetFloor);
350	    return {
351	        update: function (delta) {
352	            return moveToward(elevatorCar.position, "y", targetY, ELEVATOR_SPEED * delta);
353	        }
354	    };
355	}
356	
357	function makeDoorStep(open) {
358	    return {
359	        onStart: function () {
360	            doorAnimating = true;
361	        },
362	        update: function (delta) {
363	            const meta = elevatorCar.userData;
364	            const leftTarget = open ? meta.doorLeftOpenX : meta.doorLeftClosedX;
365	            const rightTarget = open ? meta.doorRightOpenX : meta.doorRightClosedX;
